                        out_last <= last_mem[read_ptr + 1];
                    end
                end else if (push) begin
                    out_data <= in_data;
                    out_last <= in_last;
                end
            end

            case ({push, pop})
                2'b10: occupancy <= occupancy + 1'b1;
                2'b01: occupancy <= occupancy - 1'b1;
                default: occupancy <= occupancy;
            endcase
        end
    end

endmodule

